{{ config(materialized='view') }}

with base as (
    select *,
           lower(regexp_replace(coalesce(title, ''), '[0-9]{3,}', '', 'g'))        as title_norm,
           lower(regexp_replace(coalesce(company, ''), '[^a-z0-9]+', '', 'g'))     as company_norm,
           case when lower(coalesce(location, '')) like '%remote%' then 'remote'
                else lower(regexp_replace(coalesce(location, ''), '[^a-z0-9]+', '', 'g')) end as location_norm
    from {{ ref('stg_postings') }}
)
select *,
    case
        when regexp_matches(lower(title), 'data scien|machine learning|\bml\b|artificial intelligence|\bai\b') then 'data / ML'
        when regexp_matches(lower(title), 'data engineer|analytics engineer|\betl\b|warehouse|bi developer')   then 'data engineering'
        when regexp_matches(lower(title), 'analyst|business intelligence|\bbi\b')                              then 'analytics'
        when regexp_matches(lower(title), 'product manager|project manager|program manager|product owner')     then 'product'
        when regexp_matches(lower(title), 'designer|\bux\b|\bui\b|creative')                                   then 'design'
        when regexp_matches(lower(title), 'software|developer|engineer|backend|frontend|full.?stack|devops|\bsre\b') then 'engineering'
        when regexp_matches(lower(title), 'nurse|\brn\b|lpn|physician|psychiatr|clinical|medical|therapist|pharmac|dental') then 'healthcare'
        when regexp_matches(lower(title), 'trainer|fitness|wellness|coach')                                    then 'wellness'
        when regexp_matches(lower(title), 'sales|account executive|business development|account manager|territory') then 'sales'
        when regexp_matches(lower(title), 'support|customer service|customer success')                          then 'support'
        when regexp_matches(lower(title), 'finance|accountant|controller|treasury|audit|tax|payroll')           then 'finance'
        when regexp_matches(lower(title), 'recruit|talent|people|human resources|\bhr\b')                       then 'people'
        when regexp_matches(lower(title), 'marketing|growth|brand|content|seo|social media')                    then 'marketing'
        when regexp_matches(lower(title), 'teacher|tutor|instructor|professor|education')                       then 'education'
        when regexp_matches(lower(title), 'lawyer|legal|counsel|paralegal|compliance')                          then 'legal'
        when regexp_matches(lower(title), 'assistant|coordinator|administrat|receptionist|office manager')      then 'admin'
        when regexp_matches(lower(title), 'driver|warehouse|weld|technician|maintenance|mechanic|operator|supervisor|shift|logistic|electric') then 'operations'
        else 'other'
    end as role_family,
    case
        when lower(location) like '%remote%' then 'remote'
        when regexp_matches(lower(location), 'spain|espa|madrid|barcelona|valencia|sevilla|bilbao|malaga|málaga') then 'Spain'
        when regexp_matches(lower(location), '^(us|u\.s\.|usa|united states|al|ak|az|ar|ca|co|ct|de|fl|ga|hi|id|il|in|ia|ks|ky|la|me|md|ma|mi|mn|ms|mo|mt|ne|nv|nh|nj|nm|ny|nc|nd|oh|ok|or|pa|ri|sc|sd|tn|tx|ut|vt|va|wa|wv|wi|wy)$|^us[- ]|^nyc|^sf |^s\.f\.|,\s*us$|,\s*usa$|\bunited states\b|\busa\b|new york|san francisco|los angeles|austin|seattle|boston|chicago|dallas|palo alto|mountain view|san jose|washington|arlington|san mateo|bellevue|brooklyn|nyc|san diego|miami|denver|atlanta|houston|phoenix|philadelphia|portland|minneapolis|detroit|nashville|charlotte|raleigh|salt lake|las vegas|orlando|tampa|st\.? louis|columbus|cincinnati|pittsburgh|cleveland|kansas city|sacramento|brooklyn|queens|manhattan|,\s*(al|ak|az|ar|ca|co|ct|de|fl|ga|hi|id|il|in|ia|ks|ky|la|me|md|ma|mi|mn|ms|mo|mt|ne|nv|nh|nj|nm|ny|nc|nd|oh|ok|or|pa|ri|sc|sd|tn|tx|ut|vt|va|wa|wv|wi|wy)\b') then 'United States'
        when regexp_matches(lower(location), 'united kingdom|\buk\b|london|manchester|edinburgh|birmingham|leeds') then 'United Kingdom'
        when regexp_matches(lower(location), 'german|berlin|munich|münchen|hamburg|frankfurt|cologne|düsseldorf') then 'Germany'
        when regexp_matches(lower(location), 'france|paris|lyon|toulouse|marseille|vizille|nantes|bordeaux')     then 'France'
        when regexp_matches(lower(location), 'poland|polska|warsaw|warszawa|krakow|kraków|wroclaw|wrocław')      then 'Poland'
        when regexp_matches(lower(location), 'netherlands|amsterdam|rotterdam|utrecht|eindhoven')               then 'Netherlands'
        when regexp_matches(lower(location), 'canada|toronto|vancouver|montreal|ottawa|calgary')               then 'Canada'
        when regexp_matches(lower(location), 'india|bengaluru|bangalore|hyderabad|pune|mumbai|delhi|chennai')   then 'India'
        when regexp_matches(lower(location), 'brazil|brasil|sao paulo|são paulo|rio de janeiro')                then 'Brazil'
        when regexp_matches(lower(location), 'mexico|méxico|ciudad de mexico|guadalajara|monterrey')            then 'Mexico'
        when regexp_matches(lower(location), 'colombia|bogota|bogotá|medellin|medellín|cali')                   then 'Colombia'
        when regexp_matches(lower(location), 'argentina|buenos aires|cordoba|córdoba')                          then 'Argentina'
        when regexp_matches(lower(location), 'australia|sydney|melbourne|brisbane|perth')                       then 'Australia'
        when regexp_matches(lower(location), 'ireland|dublin')                                                  then 'Ireland'
        when regexp_matches(lower(location), 'portugal|lisbon|lisboa|porto')                                    then 'Portugal'
        when regexp_matches(lower(location), 'italy|italia|milan|milano|rome|roma|turin|torino')                then 'Italy'
        when regexp_matches(lower(location), 'singapore')                                                       then 'Singapore'
        when regexp_matches(lower(location), 'japan|tokyo|osaka|kyoto')                                         then 'Japan'
        when regexp_matches(lower(location), 'korea|seoul|busan')                                               then 'South Korea'
        when regexp_matches(lower(location), 'taiwan|taipei')                                                   then 'Taiwan'
        when regexp_matches(lower(location), 'hong kong') then 'Hong Kong'
        when regexp_matches(lower(location), 'philippines|manila|cebu') then 'Philippines'
        when regexp_matches(lower(location), 'sweden|stockholm|gothenburg|malmö') then 'Sweden'
        when regexp_matches(lower(location), 'switzerland|zurich|zürich|geneva|basel|lausanne') then 'Switzerland'
        when regexp_matches(lower(location), 'belgium|brussels|antwerp|ghent') then 'Belgium'
        when regexp_matches(lower(location), 'austria|vienna|wien|graz') then 'Austria'
        when regexp_matches(lower(location), 'denmark|copenhagen|aarhus') then 'Denmark'
        when regexp_matches(lower(location), 'norway|oslo|bergen') then 'Norway'
        when regexp_matches(lower(location), 'finland|helsinki|espoo') then 'Finland'
        when regexp_matches(lower(location), 'czech|prague|praha|brno') then 'Czechia'
        when regexp_matches(lower(location), 'romania|bucharest|cluj') then 'Romania'
        when regexp_matches(lower(location), 'united arab emirates|dubai|abu dhabi') then 'UAE'
        when regexp_matches(lower(location), 'israel|tel aviv|jerusalem|herzliya') then 'Israel'
        when regexp_matches(lower(location), 'turkey|türkiye|istanbul|ankara') then 'Turkey'
        when regexp_matches(lower(location), 'south africa|cape town|johannesburg') then 'South Africa'
        when regexp_matches(lower(location), 'nigeria|lagos|abuja') then 'Nigeria'
        when regexp_matches(lower(location), 'kenya|nairobi') then 'Kenya'
        when regexp_matches(lower(location), 'pakistan|karachi|lahore|islamabad') then 'Pakistan'
        when regexp_matches(lower(location), 'bangladesh|dhaka') then 'Bangladesh'
        when regexp_matches(lower(location), 'indonesia|jakarta|bali') then 'Indonesia'
        when regexp_matches(lower(location), 'malaysia|kuala lumpur') then 'Malaysia'
        when regexp_matches(lower(location), 'vietnam|hanoi|ho chi minh') then 'Vietnam'
        when regexp_matches(lower(location), 'thailand|bangkok') then 'Thailand'
        when regexp_matches(lower(location), 'new zealand|auckland|wellington') then 'New Zealand'
        when regexp_matches(lower(location), 'chile|santiago de chile') then 'Chile'
        when regexp_matches(lower(location), 'peru|lima') then 'Peru'
        when regexp_matches(lower(location), 'ecuador|quito|guayaquil') then 'Ecuador'
        when regexp_matches(lower(location), 'costa rica|san josé') then 'Costa Rica'
        when regexp_matches(lower(location), 'panama|panamá') then 'Panama'
        when regexp_matches(lower(location), 'venezuela|caracas') then 'Venezuela'
        when regexp_matches(lower(location), 'congo')                                                           then 'DR Congo'
        when regexp_matches(lower(location), 'nepal|kathmandu')                                                 then 'Nepal'
        when regexp_matches(lower(location), 'bolivia|la paz|santa cruz')                                       then 'Bolivia'
        when regexp_matches(lower(location), 'paraguay|asuncion|asunción')                                      then 'Paraguay'
        when regexp_matches(lower(location), 'uruguay|montevideo')                                              then 'Uruguay'
        else 'unknown'
    end as country,
    lower(coalesce(location, '')) like '%remote%' as is_remote
from base
